// Every app route (K5): the chat (A2) and Command Centre (A3) kits link through these constants and
// builders and never write a path by hand, so the two waves stay file-disjoint and agree on every
// URL. expo-router's typed routes stay off (they need types generated by expo start), so a route is
// a plain string; the screen files the kits add must sit at exactly these paths. Ids are URI-encoded
// into their segment; a ticket id is the board's integer row id (GET /api/v1/tasks/{task_id}).

/** What expo-router's useLocalSearchParams() hands a screen. */
export type RouteParams = Readonly<Record<string, string | string[] | undefined>>;

/** The query parameter a new conversation reads its ticket from (the web's /chat?ticket=…). */
export const TICKET_PARAM = 'ticket';
/** The query parameter a ticket opens at one of its questions with (the web's &question=…). */
export const QUESTION_PARAM = 'question';

const ROW_ID = /^\d+$/;
const DOT_SEGMENTS: ReadonlySet<string> = new Set(['.', '..']);

/** A board row id, as the board and the web's links carry it: digits only. */
export function isTaskId(value: string): boolean {
  return ROW_ID.test(value);
}

function taskId(value: string | number): string {
  const text = String(value).trim();
  if (!isTaskId(text)) throw new TypeError('A ticket id is the board row id: digits only');
  return text;
}

/** An id that can be a path segment: not blank, not a dot segment a resolver would collapse. */
export function isUsableId(value: string): boolean {
  const text = value.trim();
  return text !== '' && !DOT_SEGMENTS.has(text);
}

function segment(value: string, what: string): string {
  if (!isUsableId(value)) throw new TypeError(`${what} is missing`);
  return encodeURIComponent(value.trim());
}

function firstParam(params: RouteParams, name: string): string | undefined {
  const value = params[name];
  return Array.isArray(value) ? value[0] : value;
}

/**
 * D31 "Ask Auto about #0419": a new conversation with the ticket as its context. The web's own
 * link has the same shape (/chat?ticket=<row id>, frontend/app/chat/page.tsx).
 */
export function chatWithTicket(id: string | number): string {
  return `/chat?${TICKET_PARAM}=${taskId(id)}`;
}

/** The ticket a new conversation was opened about, or null (none, or not a row id). */
export function ticketFromChatParams(params: RouteParams): string | null {
  const value = firstParam(params, TICKET_PARAM)?.trim();
  return value && isTaskId(value) ? value : null;
}

/** The question a ticket was opened at, or null. */
export function questionFromTicketParams(params: RouteParams): string | null {
  const value = firstParam(params, QUESTION_PARAM)?.trim();
  return value ? value : null;
}

function ticketRoute(id: string | number, questionId?: string | number | null): string {
  const path = `/cc/ticket/${taskId(id)}`;
  if (questionId === undefined || questionId === null) return path;
  return `${path}?${QUESTION_PARAM}=${segment(String(questionId), 'A question id')}`;
}

export const routes = Object.freeze({
  /** The Auto thread with the needs strip (D28): app/(app)/index.tsx (A2). */
  home: '/',
  /** Sign-in (app/(auth)/sign-in.tsx). */
  signIn: '/sign-in',
  /** Older conversations, behind the list button on home (A2). */
  chats: '/chats',
  /** One conversation (A2: app/(app)/chat/[id].tsx). */
  chat: (chatId: string) => `/chat/${segment(chatId, 'A chat id')}`,
  chatWithTicket,
  cc: Object.freeze({
    /** The Command Centre opens on the Board: app/(app)/cc/index.tsx (A3). */
    board: '/cc',
    calendar: '/cc/calendar',
    questions: '/cc/questions',
    deliverables: '/cc/deliverables',
    /** The ticket sheet, optionally at one of its questions (A3: cc/ticket/[taskId].tsx). */
    ticket: ticketRoute,
    /** A social post awaiting approval (D45; A3: cc/social/[postId].tsx). */
    social: (postId: string) => `/cc/social/${segment(postId, 'A post id')}`,
    /** One Deliverable (A3: cc/deliverables/[id].tsx). */
    deliverable: (id: string) => `/cc/deliverables/${segment(id, 'A Deliverable id')}`,
  }),
  /** Settings, opening on Account: app/(app)/settings/index.tsx. */
  settings: '/settings',
});
